/**
 * Text measurement for environments without a DOM.
 *
 * Uses per-character advance-width tables measured from Inter (the default
 * chart font) for ~2-3% accuracy on Latin text at weights 400/700.
 * Other fonts set via theme.fonts.family still get a better-than-flat-ratio
 * approximation but no accuracy guarantee.
 *
 * Tables generated by scripts/generate-char-widths.mjs — regenerate, don't
 * hand-edit.
 */

import type { MeasureTextFn } from '../types/layout';

