const AVG_CHAR_WIDTH_700 = 0.554;

// Weights < 650 scale the CHAR_WIDTHS_400 table; weights >= 650 scale
// CHAR_WIDTHS_700. The factor is 1.0 at each table's native weight.
const WEIGHT_ADJUSTMENT: Record<number, number> = {
  100: 0.9,
  200: 0.92,
  300: 0.95,
  400: 1.0,
  500: 1.02,
  600: 1.05,
  700: 1.0, // uses CHAR_WIDTHS_700 directly
  800: 1.1,
  900: 1.12,
};

interface ResolvedTable {
  table: Record<string, number>;
  avg: number;
  scale: number;
}

// Precomputed per-weight results so resolveTable never allocates. Covers the
// explicit WEIGHT_ADJUSTMENT entries plus a default (scale 1.0) fallback for
// any other weight, bucketed the same way resolveTable's branch always was.
const RESOLVED_TABLE_400_DEFAULT: ResolvedTable = {
  table: CHAR_WIDTHS_400,
  avg: AVG_CHAR_WIDTH_400,
  scale: 1.0,
};
const RESOLVED_TABLE_700_DEFAULT: ResolvedTable = {
  table: CHAR_WIDTHS_700,
  avg: AVG_CHAR_WIDTH_700,
  scale: 1.0,
};

const RESOLVED_TABLE_CACHE = new Map<number, ResolvedTable>();
for (const [weightStr, scale] of Object.entries(WEIGHT_ADJUSTMENT)) {
  const weight = Number(weightStr);
  RESOLVED_TABLE_CACHE.set(
    weight,
    weight >= 650
      ? { table: CHAR_WIDTHS_700, avg: AVG_CHAR_WIDTH_700, scale }
      : { table: CHAR_WIDTHS_400, avg: AVG_CHAR_WIDTH_400, scale },
  );
}

function resolveTable(fontWeight: number): ResolvedTable {
  const cached = RESOLVED_TABLE_CACHE.get(fontWeight);
  if (cached) return cached;
  return fontWeight >= 650 ? RESOLVED_TABLE_700_DEFAULT : RESOLVED_TABLE_400_DEFAULT;
}

function charWidthRatio(ch: string, table: Record<string, number>, avg: number): number {
  const direct = table[ch];
  if (direct !== undefined) return direct;
  const code = ch.codePointAt(0) ?? 0;
  // Combining marks (diacritics) have zero advance width
  if ((code >= 0x0300 && code <= 0x036f) || (code >= 0x1ab0 && code <= 0x1aff)) return 0;
  // CJK ideographs, kana, hangul, and fullwidth forms are full-em
  if (
    (code >= 0x1100 && code <= 0x11ff) ||
    (code >= 0x2e80 && code <= 0x9fff) ||
    (code >= 0xac00 && code <= 0xd7af) ||
    (code >= 0xf900 && code <= 0xfaff) ||
    (code >= 0xff00 && code <= 0xff60)
  )
    return 1.0;
  return avg;
}

/**
 * Estimate the average character width for a given font size and weight.
 * Used by both text width estimation and word-wrap line counting.
 */
export function estimateCharWidth(fontSize: number, fontWeight = 400): number {
  const { avg, scale } = resolveTable(fontWeight);
  return fontSize * avg * scale;
}

function measureLine(
  line: string,
  table: Record<string, number>,
  avg: number,
  scale: number,
  fontSize: number,
): number {
  let sum = 0;
  for (const ch of line) {
    sum += charWidthRatio(ch, table, avg);
  }
  return sum * fontSize * scale;
}

/**
 * Estimate the rendered width of a text string.
 *
 * Uses per-character advance widths measured from Inter (the default chart
 * font). Accurate to ~2-3% for Latin text at weights 400/700; other weights
 * are interpolated from the nearest table.
 */
export function estimateTextWidth(text: string, fontSize: number, fontWeight = 400): number {
  const { table, avg, scale } = resolveTable(fontWeight);

  if (text.includes('\n')) {
    let maxWidth = 0;
    for (const line of text.split('\n')) {
      const w = measureLine(line, table, avg, scale, fontSize);
      if (w > maxWidth) maxWidth = w;
    }
    return maxWidth;
  }
  return measureLine(text, table, avg, scale, fontSize);
}

/**
 * Width reserved for the "tryOpenData.ai" brand watermark in the bottom-right corner.
 */
export const BRAND_RESERVE_WIDTH = 130;

/** Font size of the brand watermark (px). Shared between layout and renderer. */
export const BRAND_FONT_SIZE = 12;

/** Minimum chart width to render the brand watermark (px). */
export const BRAND_MIN_WIDTH = 120;

/**
 * Width threshold below which layout tightens spacing (legend gaps, chrome
 * padding, label gaps) to maximize data area on small screens.
 */
export const COMPACT_WIDTH = 420;

/**
 * Estimate the rendered height of a text block.
 */
export function estimateTextHeight(fontSize: number, lineCount = 1, lineHeight = 1.3): number {
  return fontSize * lineHeight * lineCount;
}

/**
 * Distance from the top of a text box to its alphabetic baseline.
 *
 * Layout stores text positions as top-edge coordinates; renderers convert to
 * baseline coordinates with this ratio instead of `dominant-baseline: hanging`.
 * WebKit computes the hanging baseline from different font metrics than Blink
 * and never inherits dominant-baseline into tspans (WebKit bugs 139258 /
 * 297455), which shifted whole titles above the container on iOS Safari.
 * The 0.8 ratio matches Blink's rendered hanging position for typical UI
 * fonts (hanging sits at ~0.8 x ascent, Inter ascent ~= 0.97em) and the
 * Highcharts fontMetrics convention.
 */
export function textAscent(fontSize: number): number {
  return fontSize * 0.8;
}

// ---------------------------------------------------------------------------
// Measurer resolver — bridges heuristic ↔ injected canvas measurer
// ---------------------------------------------------------------------------

export const heuristicMeasure: MeasureTextFn = (text, fontSize, fontWeight) => ({
  width: estimateTextWidth(text, fontSize, fontWeight),
  height: estimateTextHeight(fontSize),
});

export function resolveMeasurer(measureText?: MeasureTextFn): MeasureTextFn {
  return measureText ?? heuristicMeasure;
}
